import json, csv

with open('fees.json') as f:
    fees = json.load(f)

# Belles characteristics
mcc = 5942
account_type = 'R'
capture_delay = '1'   # -> matches '<3' or None
monthly_volume = '100k-1m'   # Jan 2023 volume 113,260.42
monthly_fraud_level = '>8.3%'  # Jan 2023 fraud rate 10.31%
acquirer_country = 'US'

# Day 10 transaction characteristics
schemes = {'GlobalCard', 'NexPay', 'SwiftCharge', 'TransactPlus'}
acis = {'A', 'C', 'D', 'F', 'G'}
credits = {True, False}
intracountry_vals = {False}  # all issuing countries != US

def matches(f):
    if f['card_scheme'] not in schemes:
        return False
    if f['account_type'] and account_type not in f['account_type']:
        return False
    if f['capture_delay'] is not None and f['capture_delay'] != '<3':
        return False
    if f['monthly_fraud_level'] is not None and f['monthly_fraud_level'] != monthly_fraud_level:
        return False
    if f['monthly_volume'] is not None and f['monthly_volume'] != monthly_volume:
        return False
    if f['merchant_category_code'] and mcc not in f['merchant_category_code']:
        return False
    if f['is_credit'] is not None and f['is_credit'] not in credits:
        return False
    if f['aci'] and not (set(f['aci']) & acis):
        return False
    if f['intracountry'] is not None and bool(f['intracountry']) not in intracountry_vals:
        return False
    return True

applicable = [f['ID'] for f in fees if matches(f)]
print("Number of applicable fee IDs:", len(applicable))
print(sorted(applicable))
